def dtype_predicate(dtype, dtypes_set) -> bool:
    import numpy as np
    from pandas.api.types import is_bool_dtype, is_string_dtype, is_object_dtype
    from pandas.core.arrays import ArrowDtype

    # GH 46870: BooleanDtype._is_numeric == True but should be excluded
    if isinstance(dtype, ArrowDtype):
        dtype = dtype.numpy_dtype
    return (
        issubclass(dtype.type, tuple(dtypes_set))
        or (
            np.number in dtypes_set
            and getattr(dtype, "_is_numeric", False)
            and not is_bool_dtype(dtype)
        )
        or (
            is_object_dtype(dtype) and np.object_ in dtypes_set
        )
    )
